import React from 'react';
import { StyleSheet, Text, View, Pressable, type StyleProp, type ViewStyle } from 'react-native';

interface StatusBadgeProps {
  status: 'active' | 'inactive' | 'pending';
  label: string;
  containerStyle?: StyleProp<ViewStyle>;
}

export const StatusBadge: React.FC<StatusBadgeProps> = ({
  status,
  label,
  containerStyle,
}) => {
  const badgeBackgroundStyles: Record<StatusBadgeProps['status'], ViewStyle> = {
    active: { backgroundColor: '#DCFCE7' },
    inactive: { backgroundColor: '#F1F5F9' },
    pending: { backgroundColor: '#FEF9C3' },
  };

  const badgeTextColors: Record<StatusBadgeProps['status'], string> = {
    active: '#15803D',
    inactive: '#64748B',
    pending: '#A16207',
  };

  return (
    <View style={[styles.baseBadge, badgeBackgroundStyles[status], containerStyle]}>
      <View style={[styles.statusDot, { backgroundColor: badgeTextColors[status] }]} />
      {/* Mọi chuỗi văn bản bắt buộc phải nằm trong thẻ Text */}
      <Text style={[styles.badgeText, { color: badgeTextColors[status] }]}>
        {label.toUpperCase()}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  baseBadge: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: 9999,
    alignSelf: 'flex-start',
  },
  statusDot: {
    width: 6,
    height: 6,
    borderRadius: 3,
    marginRight: 6,
  },
  badgeText: {
    fontSize: 11,
    fontWeight: '700',
    letterSpacing: 0.5,
  },
});

import React from 'react';
import { Text, View, StyleSheet } from 'react-native';

interface SafeNotificationBadgeProps {
  unreadCount: number;
  label?: string;
}

export const SafeNotificationBadge: React.FC<SafeNotificationBadgeProps> = ({
  unreadCount,
  label,
}) => {
  // LỖI PHỔ BIẾN: {unreadCount && <Text>...</Text>} -> Nếu unreadCount = 0,
  // React Native sẽ cố gắng render số 0 dạng raw string ra ngoài View và gây CRASH!
  return (
    <View style={styles.container}>
      {/* Cách tiếp cận an toàn 1: Ép kiểu boolean tường minh */}
      {Boolean(label) && <Text style={styles.labelText}>{label}</Text>}

      {/* Cách tiếp cận an toàn 2: So sánh logic lớn hơn 0 */}
      {unreadCount > 0 ? (
        <View style={styles.badge}>
          <Text style={styles.badgeText}>
            {unreadCount > 99 ? '99+' : unreadCount}
          </Text>
        </View>
      ) : (
        <Text style={styles.emptyText}>Không có tin mới</Text>
      )}
    </View>
  );
};

