import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Text, View, StyleSheet, AppState, type AppStateStatus, BackHandler } from 'react-native';

export const LifecycleAwareScreen: React.FC = () => {
  const [appStatus, setAppStatus] = useState<AppStateStatus>(AppState.currentState);
  const appStateRef = useRef<AppStateStatus>(appStatus);
  const syncTimerRef = useRef<NodeJS.Timeout | null>(null);

  const startSync = useCallback(() => {
    if (syncTimerRef.current) return;
    console.log('[Sync] Khởi động đồng bộ dữ liệu ngầm.');
    syncTimerRef.current = setInterval(() => {
      console.log('[Sync] Đang ping server...');
    }, 5000);
  }, []);

  const stopSync = useCallback(() => {
    if (syncTimerRef.current) {
      console.log('[Sync] Dừng đồng bộ để tiết kiệm pin.');
      clearInterval(syncTimerRef.current);
      syncTimerRef.current = null;
    }
  }, []);

  useEffect(() => {
    startSync();

    // 1. Quản lý AppState toàn cục
    const subscription = AppState.addEventListener('change', (nextAppState: AppStateStatus) => {
      if (
        appStateRef.current.match(/inactive|background/) &&
        nextAppState === 'active'
      ) {
        console.log('[Lifecycle] Ứng dụng đã quay lại Foreground!');
        startSync();
      } else if (nextAppState.match(/inactive|background/)) {
        console.log('[Lifecycle] Ứng dụng chuyển sang Background/Inactive.');
        stopSync();
      }
      appStateRef.current = nextAppState;
      setAppStatus(nextAppState);
    });

    // 2. Xử lý nút Back phần cứng của Android
    const backHandler = BackHandler.addEventListener('hardwareBackPress', () => {
      console.log('[BackHandler] Chặn back vật lý hoặc hiển thị xác nhận thoát.');
      return false; // Trả về true nếu muốn tự xử lý và chặn hành động back mặc định
    });

    return () => {
      stopSync();
      subscription.remove();
      backHandler.remove();
    };
  }, [startSync, stopSync]);

  return (
    <View style={styles.container}>
      <Text style={styles.statusText}>Trạng thái ứng dụng: {appStatus}</Text>
    </View>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  statusText: { fontSize: 16, fontWeight: '600' },
});

import React, { useState, useCallback, memo } from 'react';
import { View, Text, StyleSheet, Pressable } from 'react-native';

interface CounterDisplayProps {
  count: number;
  onReset: () => void;
}

// Sử dụng React.memo để ngăn re-render không cần thiết khi component cha có state khác thay đổi
const CounterDisplay: React.FC<CounterDisplayProps> = memo(({ count, onReset }) => {
  console.log('[Render] CounterDisplay được vẽ lại');
  return (
    <View style={styles.card}>
      <Text style={styles.counterText}>Số đếm: {count}</Text>
      <Pressable style={styles.resetButton} onPress={onReset}>
        <Text style={styles.buttonText}>Đặt lại</Text>
      </Pressable>
    </View>
  );
});

CounterDisplay.displayName = 'CounterDisplay';

export const OptimizedStateContainer: React.FC = () => {
  const [count, setCount] = useState<number>(0);
  const [unrelatedState, setUnrelatedState] = useState<boolean>(false);

  // useCallback đảm bảo prop function không bị cấp phát lại địa chỉ bộ nhớ mới mỗi lần render
  const handleReset = useCallback(() => {
    setCount(0);
  }, []);

  return (
    <View style={styles.container}>
      <CounterDisplay count={count} onReset={handleReset} />

      <Pressable style={styles.incrementButton} onPress={() => setCount((prev) => prev + 1)}>
        <Text style={styles.buttonText}>Tăng số</Text>
      </Pressable>

      <Pressable
        style={styles.toggleButton}
        onPress={() => setUnrelatedState((prev) => !prev)}
      >
        <Text style={styles.buttonText}>
          Toggle State phụ (Hiện tại: {unrelatedState ? 'Bật' : 'Tắt'})
        </Text>
      </Pressable>
    </View>
  );
};

const styles = StyleSheet.create({
  container: { padding: 20, alignItems: 'center' },
  card: { padding: 16, backgroundColor: '#F8FAFC', borderRadius: 8, marginBottom: 16, width: '100%' },
  counterText: { fontSize: 18, fontWeight: '700', marginBottom: 8 },
  resetButton: { backgroundColor: '#EF4444', padding: 8, borderRadius: 6, alignItems: 'center' },
  incrementButton: { backgroundColor: '#2563EB', padding: 12, borderRadius: 8, width: '100%', marginBottom: 12, alignItems: 'center' },
  toggleButton: { backgroundColor: '#64748B', padding: 12, borderRadius: 8, width: '100%', alignItems: 'center' },
  buttonText: { color: '#FFFFFF', fontWeight: '600' },
});

import React, { useMemo } from 'react';
import { StyleSheet, View, Text, type ViewStyle } from 'react-native';

interface DynamicCardProps {
  title: string;
  progress: number; // 0 đến 100
  accentColor: string;
}

export const DynamicCard: React.FC<DynamicCardProps> = ({
  title,
  progress,
  accentColor,
}) => {
  // Tối ưu: Dùng useMemo cho phần style động phụ thuộc vào props để giữ nguyên tham chiếu nếu props không đổi
  const progressBarStyle = useMemo<ViewStyle>(() => ({
    width: `${Math.min(100, Math.max(0, progress))}%`,
    backgroundColor: accentColor,
  }), [progress, accentColor]);

  return (
    <View style={styles.cardContainer}>
      <Text style={styles.titleText}>{title}</Text>
      <View style={styles.track}>
        {/* Kết hợp style tĩnh từ StyleSheet và style động có kiểm soát */}
        <View style={[styles.bar, progressBarStyle]} />
      </View>
    </View>
  );
};

