import { Dimensions, PixelRatio } from 'react-native';

// Kích thước màn hình chuẩn của bản vẽ Figma (VD: iPhone 14 / 15: 393 x 852 pt)
const BASE_WIDTH = 393;
const { width: SCREEN_WIDTH } = Dimensions.get('window');

/**
 * Scale kích thước linh hoạt theo tỷ lệ màn hình thiết bị hiện tại
 */
export function scale(size: number): number {
  const scaleFactor = SCREEN_WIDTH / BASE_WIDTH;
  const newSize = size * scaleFactor;
  return PixelRatio.roundToNearestPixel(newSize);
}

/**
 * Trả về độ dày đường viền mỏng nhất mà thiết bị có thể hiển thị (hairline width)
 * Tránh trường hợp border 1dp hiển thị quá thô trên màn hình mật độ cao
 */
export const HAIRLINE_WIDTH: number = StyleSheetHairlineWidth();

function StyleSheetHairlineWidth(): number {
  const pixelRatio = PixelRatio.get();
  return 1 / pixelRatio;
}

