import React, { useCallback } from 'react';
import { FlatList, Text, View, StyleSheet, type ListRenderItem } from 'react-native';

interface TransactionItem {
  id: string; // Khóa định danh duy nhất ổn định từ DB
  title: string;
  amount: number;
  timestamp: number;
}

interface TransactionListProps {
  data: TransactionItem[];
}

export const TransactionList: React.FC<TransactionListProps> = ({ data }) => {
  // 1. keyExtractor PHẢI trả về chuỗi string duy nhất gắn liền với bản ghi dữ liệu
  // Tuyệt đối không dùng index!
  const keyExtractor = useCallback((item: TransactionItem) => item.id, []);

  const renderItem: ListRenderItem<TransactionItem> = useCallback(({ item }) => {
    return (
      <View style={styles.itemRow}>
        <Text style={styles.title}>{item.title}</Text>
        <Text style={styles.amount}>${item.amount.toFixed(2)}</Text>
      </View>
    );
  }, []);

  return (
    <FlatList
      data={data}
      keyExtractor={keyExtractor}
      renderItem={renderItem}
      initialNumToRender={10}
      maxToRenderPerBatch={10}
      windowSize={5}
    />
  );
};

