import React from 'react';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { Text, View } from 'react-native';

// Định nghĩa Type an toàn cho toàn bộ luồng điều hướng
export type RootStackParamList = {
  MainTabs: undefined;
  TransferWizard: { recipientId: string };
  TransactionDetail: { transactionId: string };
};

export type MainTabParamList = {
  Home: undefined;
  History: undefined;
  Settings: undefined;
};

const Stack = createNativeStackNavigator<RootStackParamList>();
const Tab = createBottomTabNavigator<MainTabParamList>();

const DummyScreen = ({ name }: { name: string }) => (
  <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
    <Text>{name}</Text>
  </View>
);

const MainTabNavigator = () => (
  <Tab.Navigator screenOptions={{ headerShown: false }}>
    <Tab.Screen name="Home" component={() => <DummyScreen name="Trang chủ" />} />
    <Tab.Screen name="History" component={() => <DummyScreen name="Lịch sử" />} />
    <Tab.Screen name="Settings" component={() => <DummyScreen name="Cài đặt" />} />
  </Tab.Navigator>
);

export const AppNavigation = () => (
  <Stack.Navigator>
    {/* Cấp cao nhất là Tabs */}
    <Stack.Screen
      name="MainTabs"
      component={MainTabNavigator}
      options={{ headerShown: false }}
    />
    {/* Màn hình dạng Modal */}
    <Stack.Screen
      name="TransferWizard"
      component={() => <DummyScreen name="Chuyển tiền" />}
      options={{ presentation: 'modal', title: 'Chuyển khoản' }}
    />
    {/* Màn hình phân cấp thông thường */}
    <Stack.Screen
      name="TransactionDetail"
      component={() => <DummyScreen name="Chi tiết giao dịch" />}
      options={{ title: 'Thông tin biên lai' }}
    />
  </Stack.Navigator>
);

import { MMKV } from 'react-native-mmkv';
import * as SecureStore from 'expo-secure-store';

// 1. Khởi tạo MMKV Storage cho Settings & Cache thông thường (siêu nhanh, synchronous)
export const appStorage = new MMKV({ id: 'app-global-storage' });

export const UserPreferencesService = {
  setDarkMode(enabled: boolean) {
    appStorage.set('user.isDarkMode', enabled);
  },
  isDarkMode(): boolean {
    return appStorage.getBoolean('user.isDarkMode') ?? false;
  },
};

// 2. Sử dụng SecureStore cho dữ liệu xác thực nhạy cảm
const AUTH_TOKEN_KEY = 'secure_auth_token';

export const SecureAuthService = {
  async saveToken(token: string): Promise<void> {
    await SecureStore.setItemAsync(AUTH_TOKEN_KEY, token, {
      keychainAccessible: SecureStore.AFTER_FIRST_UNLOCK,
    });
  },
  async getToken(): Promise<string | null> {
    return await SecureStore.getItemAsync(AUTH_TOKEN_KEY);
  },
  async clearToken(): Promise<void> {
    await SecureStore.deleteItemAsync(AUTH_TOKEN_KEY);
  },
};

