// 2. KIẾN TRÚC MỚI (JSI): Gọi trực tiếp synchronous như hàm JS thuần qua HostObject C++
interface JSIFastStorageHostObject {
  getStringSync(key: string): string | null;
  setBytesSync(key: string, value: ArrayBuffer): boolean;
}

declare const global: {
  __FastStorageJSI?: JSIFastStorageHostObject;
};

export class JSIStorageClient {
  private static instance = global.__FastStorageJSI;

  public static get(key: string): string | null {
    if (!this.instance) {
      throw new Error('JSI HostObject chưa được bind vào JS Global runtime!');
    }
    // Lệnh này thực thi đồng bộ lập tức ở tầng C++ trong thời gian nano-giây, ZERO JSON overhead
    return this.instance.getStringSync(key);
  }
}

/**
 * Utility kiểm tra runtime engine và đo lường Heap Memory của Hermes trên thiết bị thật
 */
export function checkHermesRuntimeMetrics() {
  const isHermes = Boolean((global as any).HermesInternal);

  console.log(`[Runtime]: Đang chạy trên ${isHermes ? 'Hermes Engine' : 'JavaScriptCore (JSC)'}`);

  if (isHermes && (global as any).HermesInternal) {
    // Lấy thông tin thống kê heap memory từ Hermes C++ core
    const hermesSamples = (global as any).HermesInternal.getInstrumentedStats();

    const metrics = {
      allocatedHeap: `${(hermesSamples.js_allocatedBytes / (1024 * 1024)).toFixed(2)} MB`,
      heapSize: `${(hermesSamples.js_heapSize / (1024 * 1024)).toFixed(2)} MB`,
      gcCount: hermesSamples.js_numGCs,
      gcTimeMs: `${(hermesSamples.js_gcTime / 1000).toFixed(2)} ms`,
    };

    console.table(metrics);
    return metrics;
  }

  return null;
}

