// 1. Kiến trúc Portal đơn giản hóa cho Root Modal
interface PortalContextType {
  showModal: (content: ReactNode) => void;
  hideModal: () => void;
}

const PortalContext = createContext<PortalContextType | null>(null);

export const PortalHostProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [modalContent, setModalContent] = useState<ReactNode | null>(null);

  return (
    <PortalContext.Provider
      value={{
        showModal: (content) => setModalContent(content),
        hideModal: () => setModalContent(null),
      }}
    >
      {children}
      {/* Modal được vẽ ở đỉnh của cùng một view hierarchy, không sinh native window mới */}
      {modalContent && (
        <View style={styles.overlay}>
          <Pressable style={styles.backdrop} onPress={() => setModalContent(null)} />
          <View style={styles.modalBody}>{modalContent}</View>
        </View>
      )}
    </PortalContext.Provider>
  );
};

export const useAppModal = () => {
  const ctx = useContext(PortalContext);
  if (!ctx) throw new Error('useAppModal phải được đặt trong PortalHostProvider');
  return ctx;
};

