// 1. Tạo Store tối giản, không cần Provider bao quanh Root App
export const useAuthStore = create<AuthState>((set) => ({
  token: null,
  isAuthenticated: false,
  userProfile: null,
  setAuth: (token, userProfile) =>
    set({ token, userProfile, isAuthenticated: true }),
  logout: () =>
    set({ token: null, userProfile: null, isAuthenticated: false }),
}));

// 2. Truy cập và đọc/ghi State ngoài React Lifecycle (ví dụ trong Axios Interceptor)
export function getAuthTokenForInterceptor(): string | null {
  // Đọc trực tiếp mà không cần dùng hook!
  return useAuthStore.getState().token;
}

// 3. Trong UI Component: Dùng Selector để chỉ re-render khi giá trị isAuthenticated đổi
export const UserStatusBadge: React.FC = () => {
  const isAuth = useAuthStore((state) => state.isAuthenticated);
  return <span style={{ color: isAuth ? 'green' : 'gray' }}>{isAuth ? 'Đã đăng nhập' : 'Khách'}</span>;
};

import { QueryClient } from '@tanstack/react-query';
import { onlineManager, focusManager } from '@tanstack/react-query';
