import NetInfo from '@react-native-community/netinfo';
import { AppState, type AppStateStatus, Platform } from 'react-native';
import { MMKV } from 'react-native-mmkv';

// 1. Tích hợp trạng thái mạng Online/Offline của thiết bị thật
onlineManager.setEventListener((setOnline) => {
  return NetInfo.addEventListener((state) => {
    setOnline(Boolean(state.isConnected && state.isInternetReachable));
  });
});

// 2. Tích hợp trạng thái Focus màn hình khi app quay lại Foreground
focusManager.setEventListener((handleFocus) => {
  const subscription = AppState.addEventListener('change', (status: AppStateStatus) => {
    if (Platform.OS !== 'web') {
      handleFocus(status === 'active');
    }
  });
  return () => subscription.remove();
});

// 3. Khởi tạo Storage MMKV chuyên biệt cho Query Cache
const queryStorage = new MMKV({ id: 'tanstack-query-cache' });

export const clientPersister = createSyncStoragePersister({
  storage: {
    setItem: (key, value) => queryStorage.set(key, value),
    getItem: (key) => queryStorage.getString(key) ?? null,
    removeItem: (key) => queryStorage.delete(key),
  },
});

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      gcTime: 1000 * 60 * 60 * 24, // Giữ rác bộ nhớ đệm trong 24 giờ
      staleTime: 1000 * 60 * 5, // Dữ liệu được coi là mới trong 5 phút
      retry: 2,
    },
  },
});

