// GIẢI PHÁP: KỸ THUẬT CONTEXT SPLITTING (Tách riêng State và Dispatch)

interface ThemeState {
  isDark: boolean;
}

interface ThemeDispatch {
  toggleTheme: () => void;
}

const ThemeStateContext = createContext<ThemeState | null>(null);
const ThemeDispatchContext = createContext<ThemeDispatch | null>(null);

export const ThemeProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isDark, setIsDark] = useState<boolean>(false);

  // useMemo ngăn ngừa việc tạo object mới mỗi lần Provider cha re-render
  const stateValue = useMemo(() => ({ isDark }), [isDark]);
