import React from 'react';
import { StyleSheet, View, Text } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';

export const InteractiveSpringCard: React.FC = () => {
  // 1. SharedValue được cấp phát bộ nhớ trên UI Thread, không kích hoạt React re-render
  const translationX = useSharedValue<number>(0);
  const isPressed = useSharedValue<boolean>(false);

  // 2. Gesture Pan chạy trực tiếp trên UI Thread thông qua Worklet
  const panGesture = Gesture.Pan()
    .onBegin(() => {
      isPressed.value = true;
    })
    .onUpdate((event) => {
      translationX.value = event.translationX;
    })
    .onEnd(() => {
      // Tự động bật trở về vị trí ban đầu với hiệu ứng vật lý lò xo mượt mà
      translationX.value = withSpring(0, { damping: 15, stiffness: 120 });
    })
    .onFinalize(() => {
      isPressed.value = false;
    });

  // 3. Animated Style được tính toán theo nhịp 120fps trên UI Thread
  const animatedStyle = useAnimatedStyle(() => ({
    transform: [
      { translateX: translationX.value },
      { scale: withTiming(isPressed.value ? 1.05 : 1, { duration: 150 }) },
    ],
  }));

  return (
    <View style={styles.container}>
      <GestureDetector gesture={panGesture}>
        <Animated.View style={[styles.card, animatedStyle]}>
          <Text style={styles.text}>Kéo tôi sang trái/phải</Text>
        </Animated.View>
      </GestureDetector>
    </View>
  );
};

