});

import React from 'react';
import { StyleSheet, View, Text } from 'react-native';
import { Gesture, GestureDetector, GestureHandlerRootView } from 'react-native-gesture-handler';
import Animated, { useSharedValue, useAnimatedStyle, withDecay } from 'react-native-reanimated';

export const NativeGestureSwipeDemo: React.FC = () => {
  const offsetX = useSharedValue<number>(0);

  // Khai báo cử chỉ vuốt hoàn toàn theo chuẩn RNGH v2 hiện đại
  const pan = Gesture.Pan()
    .onChange((event) => {
      // Toạ độ được cập nhật đồng bộ trực tiếp ở tầng Native UI Thread
      offsetX.value += event.changeX;
    })
    .onEnd((event) => {
      // Quán tính vuốt vật lý tự nhiên (Decay physics)
      offsetX.value = withDecay({
        velocity: event.velocityX,
        clamp: [-150, 150],
      });
    });

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: offsetX.value }],
  }));

  return (
    // GestureHandlerRootView là bắt buộc ở cấp root app hoặc màn hình cha
    <GestureHandlerRootView style={styles.container}>
      <GestureDetector gesture={pan}>
        <Animated.View style={[styles.box, animatedStyle]}>
          <Text style={styles.text}>Vuốt Native mượt mà</Text>
        </Animated.View>
      </GestureDetector>
    </GestureHandlerRootView>
  );
};

