import React, { useEffect } from 'react';
import { View, Text, Alert } from 'react-native';
import * as Updates from 'expo-updates';

export const useAutoOTAUpdateCheck = () => {
  useEffect(() => {
    async function checkAndUpdate() {
      if (__DEV__) return; // Bỏ qua trong môi trường development

      try {
        const update = await Updates.checkForUpdateAsync();
        if (update.isAvailable) {
          console.log('[OTA] Đã phát hiện bản vá mới. Đang tải ngầm...');
          await Updates.fetchUpdateAsync();

          Alert.alert(
            'Cập nhật hoàn tất',
            'Bản vá lỗi mới đã được nạp thành công. Bạn có muốn khởi động lại ngay?',
            [
              { text: 'Để sau', style: 'cancel' },
              { text: 'Khởi động lại', onPress: () => Updates.reloadAsync() },
            ]
          );
        }
      } catch (error) {
        console.warn('[OTA] Lỗi khi kiểm tra cập nhật:', error);
      }
    }

    checkAndUpdate();
  }, []);
};

