/**
 * Utility ghi log hiệu năng chuẩn để hiển thị trực quan trong React Native DevTools Console
 */
export function profileNativeExecution(taskName: string, taskFn: () => void) {
  if (__DEV__) {
    // Sử dụng Performance API chuẩn tương thích hoàn hảo với DevTools CDP
    const startMark = `${taskName}_start`;
    const endMark = `${taskName}_end`;

    performance.mark(startMark);
    taskFn();
    performance.mark(endMark);

    performance.measure(taskName, startMark, endMark);
    const entries = performance.getEntriesByName(taskName);
    const duration = entries[entries.length - 1]?.duration;

    console.log(`%c[DevTools Perf] ${taskName}: ${duration?.toFixed(2)} ms`, 'color: #0284C7; font-weight: bold;');
  } else {
    taskFn();
  }
}

