import { useCallback } from 'react';
import { Platform, Alert } from 'react-native';
import {
  check,
  request,
  openSettings,
  PERMISSIONS,
  RESULTS,
  type Permission,
} from 'react-native-permissions';

const CAMERA_PERMISSION: Permission = Platform.select({
  ios: PERMISSIONS.IOS.CAMERA,
  android: PERMISSIONS.ANDROID.CAMERA,
})!;

export const useCameraPermission = () => {
  const requestCameraAccess = useCallback(async (): Promise<boolean> => {
    try {
      const currentStatus = await check(CAMERA_PERMISSION);

      if (currentStatus === RESULTS.GRANTED) {
        return true;
      }

      if (currentStatus === RESULTS.DENIED) {
        const requestResult = await request(CAMERA_PERMISSION);
        return requestResult === RESULTS.GRANTED;
      }

      if (currentStatus === RESULTS.BLOCKED) {
        Alert.alert(
          'Quyền Camera bị từ chối',
          'Ứng dụng cần quyền Camera để quét mã QR thanh toán. Vui lòng cấp quyền trong phần Cài đặt của điện thoại.',
          [
            { text: 'Hủy bỏ', style: 'cancel' },
            { text: 'Mở Cài đặt', onPress: () => openSettings() },
          ]
        );
        return false;
      }

      return false;
    } catch (error) {
      console.error('[Permission Error]:', error);
      return false;
    }
  }, []);

  return { requestCameraAccess };
};

