import React, { useEffect, useRef } from 'react';
import { Platform } from 'react-native';
import * as Notifications from 'expo-notifications';
import { useNavigation } from '@react-navigation/native';

// 1. Cấu hình hành vi hiển thị popup thông báo khi app ĐANG MỞ (Foreground)
Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: false,
  }),
});

export const usePushNotificationManager = () => {
  const navigation = useNavigation<any>();
  const responseListener = useRef<Notifications.EventSubscription | null>(null);

  useEffect(() => {
    // 2. Tạo Notification Channel bắt buộc cho Android
    if (Platform.OS === 'android') {
      Notifications.setNotificationChannelAsync('orders-channel', {
        name: 'Thông báo đơn hàng',
        importance: Notifications.AndroidImportance.MAX,
        vibrationPattern: [0, 250, 250, 250],
      });
    }

    // 3. Xử lý trường hợp App mở từ KILLED STATE do người dùng bấm vào thông báo
    Notifications.getLastNotificationResponseAsync().then((response) => {
      if (response) {
        const orderId = response.notification.request.content.data?.orderId;
        if (orderId) {
          navigation.navigate('OrderDetail', { orderId });
        }
      }
    });

    // 4. Lắng nghe khi người dùng bấm vào thông báo khi app đang ở BACKGROUND
    responseListener.current = Notifications.addNotificationResponseReceivedListener((response) => {
      const orderId = response.notification.request.content.data?.orderId;
      if (orderId) {
        navigation.navigate('OrderDetail', { orderId });
      }
    });

    return () => {
      if (responseListener.current) responseListener.current.remove();
    };
  }, [navigation]);
};

/**
 * Khung đánh giá ma trận kiến trúc Mobile Tech Stack (Architectural Decision Matrix)
 */
export interface ArchitectureCriteria {
  criterion: string;
  weight: number; // Trọng số từ 1 đến 5
  reactNativeScore: number; // Điểm 1-10
  flutterScore: number;
  pureNativeScore: number;
}

export const MOBILE_TECH_STACK_MATRIX: ArchitectureCriteria[] = [
  {
    criterion: 'Tốc độ phát triển & Chia sẻ code với Web (Time-to-Market)',
    weight: 5,
    reactNativeScore: 9, // Chia sẻ TypeScript, validation Zod, state stores
    flutterScore: 6,
    pureNativeScore: 4,
  },
  {
    criterion: 'Trải nghiệm UI/UX chuẩn Native & Khả năng tiếp cận Accessibility',
    weight: 5,
    reactNativeScore: 9, // Ánh xạ 100% Host Views UIKit & Jetpack
    flutterScore: 7, // Tự vẽ canvas, cần giả lập Cupertino/Material
    pureNativeScore: 10,
  },
  {
    criterion: 'Cập nhật nóng không qua kiểm duyệt Store (OTA Updates)',
    weight: 4,
    reactNativeScore: 10, // EAS Update / Expo Updates hoàn hảo
    flutterScore: 4, // Shorebird khả dụng nhưng hạn chế
    pureNativeScore: 1, // Không hỗ trợ OTA hợp lệ
  },
  {
    criterion: 'Hiệu năng tính toán đồ họa 3D/Xử lý audio cấp thấp',
    weight: 4,
    reactNativeScore: 7,
    flutterScore: 8,
    pureNativeScore: 10, // Metal / Vulkan / C++ truy xuất tối đa
  },
];

export function calculateRecommendedStack(): string {
  let rnTotal = 0;
  let flutterTotal = 0;
  let nativeTotal = 0;

  for (const item of MOBILE_TECH_STACK_MATRIX) {
    rnTotal += item.reactNativeScore * item.weight;
    flutterTotal += item.flutterScore * item.weight;
    nativeTotal += item.pureNativeScore * item.weight;
  }

  return `[Kết quả phân tích có trọng số]: RN: ${rnTotal}đ | Flutter: ${flutterTotal}đ | Pure Native: ${nativeTotal}đ`;
}

import React from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { View, Text, Pressable, StyleSheet } from 'react-native';
import { create } from 'zustand';

// 1. Quản lý trạng thái xác thực bằng Zustand Store tối giản
interface AuthStore {
  token: string | null;
  login: (fakeToken: string) => void;
  logout: () => void;
}

export const useAuthStore = create<AuthStore>((set) => ({
  token: null,
  login: (fakeToken) => set({ token: fakeToken }),
  logout: () => set({ token: null }),
}));

const Stack = createNativeStackNavigator();

// 2. Màn hình xác thực (Auth Stack)
const LoginScreen = () => {
  const login = useAuthStore((state) => state.login);
  return (
    <View style={styles.center}>
      <Text style={styles.title}>Màn hình đăng nhập</Text>
      <Pressable style={styles.btn} onPress={() => login('jwt_secure_access_token')}>
        <Text style={styles.btnText}>Đăng nhập ngay</Text>
      </Pressable>
    </View>
  );
};

// 3. Màn hình ứng dụng chính (App Stack)
const DashboardScreen = () => {
  const logout = useAuthStore((state) => state.logout);
  return (
    <View style={styles.center}>
      <Text style={styles.title}>Khu vực bảo mật: Số dư 50.000.000 đ</Text>
      <Pressable style={[styles.btn, styles.logoutBtn]} onPress={logout}>
        <Text style={styles.btnText}>Đăng xuất an toàn</Text>
      </Pressable>
    </View>
  );
};

// 4. Root Navigator: Phân tách tuyệt đối giữa 2 stack bằng Conditional Rendering
export const RootSecureNavigation = () => {
  const isAuthenticated = useAuthStore((state) => Boolean(state.token));

  return (
    <NavigationContainer>
      <Stack.Navigator screenOptions={{ headerShown: false }}>
        {isAuthenticated ? (
          // Khi đăng nhập thành công, chỉ duy nhất AppStack tồn tại trong cây view
          <Stack.Group>
            <Stack.Screen name="Dashboard" component={DashboardScreen} />
          </Stack.Group>
        ) : (
          // Khi đăng xuất, AppStack bị UNMOUNT hoàn toàn khỏi RAM, không thể back lại!
          <Stack.Group screenOptions={{ animationTypeForReplace: 'pop' }}>
            <Stack.Screen name="Login" component={LoginScreen} />
          </Stack.Group>
        )}
      </Stack.Navigator>
    </NavigationContainer>
  );
};

