import React, { useMemo } from 'react';
import { FlatList, Platform, View, Text, StyleSheet } from 'react-native';

interface HeavyFeedItem {
  id: string;
  title: string;
  content: string;
}

export const AdaptiveOptimizedList: React.FC<{ data: HeavyFeedItem[] }> = ({ data }) => {
  // Chiến lược Trade-off thích ứng: Trên iOS phần cứng GPU rất mạnh và quản lý bộ nhớ tốt,
  // trong khi Android tầm trung dễ bị OOM -> Cấu hình linh hoạt theo nền tảng
  const shouldRemoveClipped = useMemo(() => {
    // Trên Android luôn ưu tiên cứu vãn bộ nhớ RAM
    if (Platform.OS === 'android') return true;
    // Trên iOS chỉ bật nếu danh sách cực lớn (> 200 items)
    return data.length > 200;
  }, [data.length]);

  return (
    <FlatList
      data={data}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View style={styles.card}>
          <Text style={styles.title}>{item.title}</Text>
          <Text style={styles.content}>{item.content}</Text>
        </View>
      )}
      // Áp dụng thuộc tính có chủ đích kèm hiểu biết trade-off sâu sắc
      removeClippedSubviews={shouldRemoveClipped}
      maxToRenderPerBatch={10}
      windowSize={7} // Tăng nhẹ windowSize để mở rộng vùng đệm, giảm thiểu hiện tượng chớp trắng
    />
  );
};

