/**
 * Marker chuẩn cho Profiling: Đánh dấu các mốc thời gian để hiển thị trong Systrace / Perfetto / DevTools
 */
import { NativeModules } from 'react-native';

export const PerformanceTrace = {
  startTrace(traceName: string) {
    if (__DEV__) {
      console.time(traceName);
      // Gửi tín hiệu vào hệ thống Systrace của Android / Signpost của iOS nếu có Native Module
      NativeModules.CustomSystraceBridge?.beginSection?.(traceName);
    }
  },

  endTrace(traceName: string) {
    if (__DEV__) {
      NativeModules.CustomSystraceBridge?.endSection?.();
      console.timeEnd(traceName);
    }
  },

  // Wrapper chuẩn đo lường một hàm async nghiệp vụ phức tạp
  async measureAsync<T>(name: string, asyncFn: () => Promise<T>): Promise<T> {
    this.startTrace(name);
    try {
      return await asyncFn();
    } finally {
      this.endTrace(name);
    }
  },
};

