// 2. Phía TypeScript: Sử dụng trực tiếp hàm C++ với tốc độ cực đại
interface NativeCryptoJSI {
  sha256Sync(rawText: string): string;
}
declare const global: { __CryptoJSI?: NativeCryptoJSI };

export function fastHash(data: string): string {
  if (!global.__CryptoJSI) {
    throw new Error('JSI Crypto Engine chưa được khởi tạo');
  }
  // Gọi đồng bộ trực tiếp tới C++ core qua JSI pointer, ZERO JSON overhead
  return global.__CryptoJSI.sha256Sync(data);
}

/**
 * Mô phỏng máy trạng thái 3 giai đoạn của Fabric Renderer Pipeline (Render -> Commit -> Mount)
 */
export type FabricPhase = 'RENDER_JS' | 'COMMIT_SHADOW_TREE_CPP' | 'MOUNT_NATIVE_VIEWS';

export interface FabricCommitEvent {
  phase: FabricPhase;
  timestamp: number;
  treeRevision: number;
  isSynchronous: boolean;
}

export class FabricPipelineMonitor {
  private static currentRevision = 0;

  public static traceCommit(isHighPriorityInput: boolean): FabricCommitEvent {
    this.currentRevision++;
    const event: FabricCommitEvent = {
      phase: 'COMMIT_SHADOW_TREE_CPP',
      timestamp: performance.now(),
      treeRevision: this.currentRevision,
      // Nếu là tương tác người dùng ưu tiên cao, Fabric ép Render đồng bộ tức thì
      isSynchronous: isHighPriorityInput,
    };

    console.log(`[Fabric Commit] Revision #${event.treeRevision} | Sync: ${event.isSynchronous}`);
    return event;
  }
}

