/**
 * Đo lường hiệu năng tổng thể của combo Hermes + New Architecture
 */
export function getEngineSynergyReport() {
  const hasHermes = Boolean((global as any).HermesInternal);
  const hasFabric = Boolean((global as any).nativeFabricUIManager);
  const isBridgeless = Boolean((global as any).RN$Bridgeless);

  const isOptimalCombo = hasHermes && hasFabric && isBridgeless;

  return {
    engine: hasHermes ? 'Hermes (AOT Bytecode)' : 'JSC/V8',
    fabricRenderer: hasFabric ? 'Hoạt động (C++ Shadow Tree)' : 'Không khả dụng',
    bridgelessMode: isBridgeless ? 'Kích hoạt' : 'Vẫn dùng Bridge',
    verdict: isOptimalCombo
      ? 'Ứng dụng đạt cấu hình hiệu năng tối thượng chuẩn 2026!'
      : 'Chưa đạt cấu hình tối ưu. Vui lòng bật đầy đủ New Architecture.',
  };
}

