import React from 'react';
import { StyleSheet, View, Text } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  runOnJS,
} from 'react-native-reanimated';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';

export const WorkletUnderTheHoodDemo: React.FC = () => {
  // 1. Con trỏ bộ nhớ dùng chung C++ tồn tại độc lập với React State
  const scale = useSharedValue<number>(1);

  // Hàm callback thông thường chạy trên JavaScript Thread
  const notifyJsThread = (finalScale: number) => {
    console.log('[JS Thread] Animation hoàn thành với scale:', finalScale);
  };

  // 2. Gesture logic chạy 100% dưới dạng worklet trên UI Thread
  const pinchGesture = Gesture.Pinch()
    .onUpdate((event) => {
      // Cập nhật tức thì ở nhịp quét 120fps trên UI Thread
      scale.value = event.scale;
    })
    .onEnd(() => {
      scale.value = withSpring(1, { damping: 10 }, (isFinished) => {
        if (isFinished) {
          // 3. Giao tiếp ngược từ UI Thread về JS Thread an toàn bằng runOnJS
          runOnJS(notifyJsThread)(scale.value);
        }
      });
    });

  // 4. Hàm này chạy trên UI JS Runtime
  const animatedStyle = useAnimatedStyle(() => {
    'worklet'; // Chỉ thị worklet chạy trên UI Thread
    return {
      transform: [{ scale: scale.value }],
    };
  });

  return (
    <View style={styles.container}>
      <GestureDetector gesture={pinchGesture}>
        <Animated.View style={[styles.box, animatedStyle]}>
          <Text style={styles.text}>Pinch Zoom</Text>
        </Animated.View>
      </GestureDetector>
    </View>
  );
};

