          antiAlias={true}
        >
          <LinearGradient
            start={vec(0, 0)}
            end={vec(380, 0)}
            colors={['#3B82F6', '#10B981']}
          />
        </Path>

        {/* Hiệu ứng kính mờ Glassmorphism cao cấp chạy trực tiếp trên GPU Shaders */}
        <BackdropFilter filter={<Blur blur={12} />} clip={{ x: 40, y: 30, width: 220, height: 80 }}>
          <Fill color="rgba(255, 255, 255, 0.2)" />
        </BackdropFilter>
      </Canvas>
    </View>
  );
};

