  async saveSessionToken(token: string): Promise<void> {
    await SecureStore.setItemAsync('auth_session_token', token, {
      keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY,
      requireAuthentication: false, // Có thể bật true nếu bắt buộc xác thực sinh trắc học trước khi mở token
    });
  },

  async getSessionToken(): Promise<string | null> {
    return await SecureStore.getItemAsync('auth_session_token');
  },

  // 2. Kiểm tra tính toàn vẹn của thiết bị (Jailbreak / Root Detection)
